\subsection*{Derivation bridges}

\begin{lemma}[Impact parameters bounded by the aperture]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:impactParam_le_aperture}
\lean{IPhO2026.Problem2.B2.impactParam\_le\_aperture}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:mirrorCircle}
Every mirror-collected impact parameter is bounded in absolute value by the
aperture radius: for every absorbed impact parameter $y$,
$|\langle \mathrm{incidentPt}\,y - C, e\rangle| \le R$.
\end{lemma}
\begin{proof}
The incidence point lies on the mirror circle, so
$\|\mathrm{incidentPt}\,y - C\| = R$; since $\|e\| = 1$, Cauchy--Schwarz
for the inner product gives
$|\langle \mathrm{incidentPt}\,y - C, e\rangle| \le
\|\mathrm{incidentPt}\,y - C\| \cdot \|e\| = R$.
\end{proof}

\begin{lemma}[Collected width equals the radius]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth_eq_radius}
\lean{IPhO2026.Problem2.B2.collectedWidth\_eq\_radius}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:impactParam_le_aperture}
The transverse width collected by the half-cylinder mirror on the
container's side equals $R$ (one full half of the aperture $2R$):
$\mathrm{collectedWidth} = R$.
\end{lemma}
\begin{proof}
Upper bound: every impact-parameter readout is at most $R$ by
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:impactParam_le_aperture},
so the defining supremum does not exceed $R$.  Lower bound: the B.1
calibration with $\theta \in (0, \pi/2)$ gives $a \le R$, and full side
coverage together with the gap-free family realizes every impact parameter
in $(0, a)$ up to the aperture edge, forcing the supremum to be at least
$R$.
\end{proof}

\begin{lemma}[Power ratio as width ratio]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_eq_width_ratio}
\lean{IPhO2026.Problem2.B2.power\_ratio\_eq\_width\_ratio}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:PowerBudget, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth_eq_radius}
Power ratio from the width accounting only:
$P / P_0 = R / (2a)$.  With the B.1 calibration this becomes the target
trigonometric form.
\end{lemma}
\begin{proof}
Substitute the two budget identities
$P = I \cdot \mathrm{collectedWidth}$ and $P_0 = I \cdot (2a)$; the common
positive intensity $I$ cancels in the ratio, and
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth_eq_radius}
replaces $\mathrm{collectedWidth}$ by $R$.
\end{proof}

\begin{lemma}[Radius-over-diameter trigonometric bridge]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:radius_over_diameter_eq}
\lean{IPhO2026.Problem2.B2.radius\_over\_diameter\_eq}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:B1Calibration, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams}
Trigonometric bridge (B.1 calibration, elementary): for
$\theta \in (0, \pi/2)$ satisfying the calibration
$a = R \sin\theta - (R/2)\sin(2\theta)$,
\[
\frac{R}{2a} = \frac{1}{1 - \cos\theta} .
\]
\end{lemma}
\begin{proof}
Substitute the calibration and factor:
$2a = 2R\sin\theta - R\sin(2\theta)
= 2R\sin\theta\,(1 - \cos\theta)$ by the double-angle identity
$\sin(2\theta) = 2\sin\theta\cos\theta$.  Since $\theta \in (0, \pi/2)$,
$\sin\theta \ne 0$, so cancelling $R\sin\theta$ against the numerator $R$
leaves $R/(2a) = 1/(1 - \cos\theta)$.
\end{proof}

\subsection*{Target value theorem}

\begin{theorem}[Power ratio in terms of the maximum incidence angle]
\label{thm:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_in_terms_of_theta_max}
\lean{IPhO2026.Problem2.B2.power\_ratio\_in\_terms\_of\_theta\_max}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:PowerBudget, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:B1Calibration, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_eq_width_ratio, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:radius_over_diameter_eq}
\textbf{(Target, T2-B2.)}  For the cooker of Figure~2f with absorbed-ray
bookkeeping, power budget, and maximum incidence angle $\theta_{\max}$
satisfying
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec} and the
B.1 calibration, the ratio of the received power $P$ to the unmirrored
power $P_0$ is
\[
\frac{P}{P_0} = \frac{1}{1 - \cos\theta_{\max}} .
\]
This is the recorded official answer of part B.2; the value is
conclusion-side only, confined to this target theorem (no hypothesis states
it in advance).
\end{theorem}
\begin{proof}
The specification
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec} supplies
$\theta_{\max} \in (0, \pi/2)$, so
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:radius_over_diameter_eq}
applies under the B.1 calibration and gives
$R/(2a) = 1/(1 - \cos\theta_{\max})$; chaining with
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_eq_width_ratio},
$P/P_0 = R/(2a)$, yields the claim.
\end{proof}

